import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"小旻","description":"","frontmatter":{"title":"小旻","date":"2026-11-08T00:00:00.000Z","seq":35,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/小旻.md","filePath":"blogs/诗经·小雅/小旻.md"}'),p={name:"blogs/诗经·小雅/小旻.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="小旻" tabindex="-1">小旻 <a class="header-anchor" href="#小旻" aria-label="Permalink to &quot;小旻&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">旻天疾威，敷于下土。谋犹回遹，何日斯沮？谋臧不从，不臧覆用。我视谋犹，亦孔之邛。</p><p class="poem-stanza">潝潝訿訿，亦孔之哀。谋之其臧，则具是违。谋之不臧，则具是依。我视谋犹，伊于胡厎。</p><p class="poem-stanza">我龟既厌，不我告犹。谋夫孔多，是用不集。发言盈庭，谁敢执其咎？如匪行迈谋，是用不得于道。</p><p class="poem-stanza">哀哉为犹，匪先民是程，匪大犹是经。维迩言是听，维迩言是争。如彼筑室于道谋，是用不溃于成。</p><p class="poem-stanza">国虽靡止，或圣或否。民虽靡膴，或哲或谋，或肃或艾。如彼泉流，无沦胥以败。</p><p class="poem-stanza">不敢暴虎，不敢冯河。人知其一，莫知其他。战战兢兢，如临深渊，如履薄冰。</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
